<?php
/**
 * Loads the "Event settings" sidebar panel in the editor.
 *
 * @package CommunityEvents
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

function community_events_enqueue_editor_assets() {
	$screen = get_current_screen();
	if ( ! $screen || 'ce_event' !== $screen->post_type ) {
		return;
	}

	// Generated by the build: lists the wp-* scripts this file needs and a version hash.
	$asset = require dirname( __DIR__ ) . '/build/event-settings/index.asset.php';

	wp_enqueue_script(
		'community-events-settings',
		plugins_url( 'build/event-settings/index.js', __DIR__ ),
		$asset['dependencies'],
		$asset['version'],
		true
	);
	wp_set_script_translations( 'community-events-settings', 'wp-community-events-block' );
}
add_action( 'enqueue_block_editor_assets', 'community_events_enqueue_editor_assets' );
